from prefect import flow, task

@task(retries=3, retry_delay_seconds=300)
def ingest_api() -> str:
    print("Pulling records from source API")
    return "s3://raw/orders/2026-07-02/"

@task
def load_warehouse(raw_path: str) -> str:
    print(f"Loading {raw_path} into warehouse staging")
    return "analytics.staging_orders"

@task
def dbt_transform(staging_table: str) -> str:
    print(f"Transforming {staging_table} with dbt")
    return "analytics.fct_orders"

@task
def refresh_bi(model: str) -> None:
    print(f"Refreshing BI/ML on {model}")

@flow(name="daily_elt_pipeline")
def daily_elt():
    # Dependencies are implied by passing outputs as inputs
    raw = ingest_api()
    staging = load_warehouse(raw)
    fct = dbt_transform(staging)
    refresh_bi(fct)

if __name__ == "__main__":
    daily_elt()
